const a="/api";async function i(n,t){const o=await n.text();let r=null;if(o)try{r=JSON.parse(o)}catch{throw n.ok?new Error(`${t}（服务返回了无法解析的响应）`):new Error(`${t}（服务返回了非 JSON 响应，通常表示后端未启动或代理失败）`)}if(!n.ok){const e=r;throw new Error((e==null?void 0:e.error)||t)}if(!r)throw new Error(`${t}（服务返回空响应，通常表示后端未启动或代理失败）`);return r}async function s(n){const t=await fetch(`${a}/manage/auth/register`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(n)});return i(t,"注册失败")}async function c(n){const t=await fetch(`${a}/manage/auth/login`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(n)});return i(t,"登录失败")}async function h(n,t){const o=await fetch(`${a}/me/bootstrap/credentials`,{method:"POST",headers:{Authorization:`Bearer ${n}`,"Content-Type":"application/json"},body:JSON.stringify(t)});return i(o,"更新首次登录信息失败")}export{h as c,c as l,s as r};
